#!/usr/bin/env ts-node
/**
 * PLATFORM-HELD-BYTES Stage A WI-2 — the canonical text function and the shared decode vectors.
 *
 * Plan: cline_docs/reviews/platform-held-bytes-2026-10-13/STAGE-A-PLAN.md WI-2. Contract: P3-SERVICE-CONTRACT.md §3.
 * Vectors: scripts/fixtures/held-bytes/decode-vectors.json, GENERATED by gen-legacy-python-text.py (python3 -I) — never
 * hand-edited. Secret-shaped vectors (V19–V21) are built at RUNTIME here (gitleaks discipline).
 *
 * Directions tested separately:
 *   ACCEPT   — V1–V6, V13–V17 text, facts and hash byte-exact; V1–V4 share one hash; no NFKC, no extra line splits.
 *   REFUSE   — V7–V12, V18 by name; V20/V21 ⇒ escaped-secret-residual; lone surrogate before any Buffer/hash.
 *   LEGACY   — every vector's generated class holds through checkLegacyText → canonicalBase (BC-A3).
 *   STATIC   — env-free module, one hash, the deep walk only inside the residual comparison, one R10-off predicate.
 */
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import {
  decodeCanonicalBytes,
  checkLegacyText,
  canonicalBase,
  countPlaceholders,
  countLines,
  DECODE_VERSION,
} from '../lib/agents/harness/held-bytes/canonical-text';
import { R10_VERSION } from '../lib/agents/harness/redact-artifact-secrets';
import { HELD_FILE_CAP } from '../lib/agents/harness/held-bytes/caps';

console.log('🧾 held-bytes canonical text (WI-2)\n');

let passed = 0;
let failed = 0;
function test(description: string, fn: () => void) {
  try {
    fn();
    console.log(`✅ ${description}`);
    passed++;
  } catch (error) {
    console.error(`❌ ${description}`);
    if (error instanceof Error) console.error(`   Error: ${error.message}`);
    failed++;
  }
}
function eq(actual: unknown, expected: unknown, what = '') {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${what}expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function ok(cond: unknown, what: string) { if (!cond) throw new Error(what); }
const sha = (s: string) => crypto.createHash('sha256').update(Buffer.from(s, 'utf8')).digest('hex');
const fromB64 = (b: string) => Buffer.from(b, 'base64');

interface Vector {
  id: string;
  rawB64: string;
  operator: { result: 'ok'; textB64: string; facts: Record<string, unknown>; textSha256TestOnly: string }
    | { result: 'refuse'; refusal: string; offset: number };
  legacyPythonText: { textB64: string } | null;
  legacyClass: 'legacy-equal' | 'legacy-refused' | 'legacy-service-error' | 'legacy-accepts-operator-refuses';
  legacyRefusal?: string;
}
const doc = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'held-bytes', 'decode-vectors.json'), 'utf8'));
const V: Vector[] = doc.vectors;
const byId = (id: string) => { const v = V.find((x) => x.id === id); if (!v) throw new Error(`missing ${id}`); return v; };

// ── vector file sanity ─────────────────────────────────────────────────────────────────────────────────────────────
test('vector file: generated, 18 vectors, decodeVersion matches the module', () => {
  eq(V.length, 18, 'vectors ');
  eq(doc.decodeVersion, DECODE_VERSION, 'decodeVersion ');
  ok(String(doc._comment).includes('GENERATED'), 'header must say GENERATED');
});

test('vector file equals its generator\'s output (code review CR-N6) — or the check is SKIPPED BY NAME when python3 is absent', () => {
  const { spawnSync } = require('child_process') as typeof import('child_process');
  const os = require('os') as typeof import('os');
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'heldvec-'));
  const gen = path.join(__dirname, 'fixtures', 'held-bytes', 'gen-legacy-python-text.py');
  fs.copyFileSync(gen, path.join(tmp, 'gen.py'));
  const r = spawnSync('python3', ['-I', path.join(tmp, 'gen.py')], { encoding: 'utf8' });
  if (r.error || r.status === null) { console.log('   ⚪ SKIPPED: python3 not available — the generator check did NOT run'); return; }
  ok(r.status === 0, `generator failed: ${r.stderr}`);
  const regenerated = fs.readFileSync(path.join(tmp, 'decode-vectors.json'), 'utf8');
  const committed = fs.readFileSync(path.join(__dirname, 'fixtures', 'held-bytes', 'decode-vectors.json'), 'utf8');
  fs.rmSync(tmp, { recursive: true, force: true });
  ok(regenerated === committed, 'decode-vectors.json differs from the generator output — regenerate it, never hand-edit');
});

// ── operator decode: ACCEPT ────────────────────────────────────────────────────────────────────────────────────────
for (const v of V) {
  if (v.operator.result !== 'ok') continue;
  const op = v.operator;
  test(`${v.id} decodes: text, facts and textSha256 byte-exact`, () => {
    const r = decodeCanonicalBytes(fromB64(v.rawB64), HELD_FILE_CAP);
    ok(r.ok, `expected ok, got ${JSON.stringify(r)}`);
    if (!r.ok) return;
    eq(Buffer.from(r.text, 'utf8').toString('base64'), op.textB64, 'text ');
    eq(r.facts, op.facts, 'facts ');
    eq(sha(r.text), op.textSha256TestOnly, 'sha ');
  });
}
test('V1–V4 share one hash (identity lives in canonical space; facts carry the difference)', () => {
  const hashes = ['V1', 'V2', 'V3', 'V4'].map((id) => {
    const r = decodeCanonicalBytes(fromB64(byId(id).rawB64), HELD_FILE_CAP);
    if (!r.ok) throw new Error(`${id} refused`);
    return sha(r.text);
  });
  eq(new Set(hashes).size, 1, 'distinct hashes ');
});
test('V15 keeps NBSP and the ellipsis (no NFKC); V14 does not split on U+2028/FF; V16 keeps trailing whitespace', () => {
  const d15 = decodeCanonicalBytes(fromB64(byId('V15').rawB64), HELD_FILE_CAP);
  ok(d15.ok && d15.text === 'x …\n', 'V15 text');
  const d14 = decodeCanonicalBytes(fromB64(byId('V14').rawB64), HELD_FILE_CAP);
  ok(d14.ok && d14.facts.lineCount === 1, 'V14 is one line');
  const d16 = decodeCanonicalBytes(fromB64(byId('V16').rawB64), HELD_FILE_CAP);
  ok(d16.ok && d16.text === 'a \t\n\n', 'V16 text');
});
test('V13 double BOM keeps exactly one U+FEFF (ignoreBOM: true)', () => {
  const r = decodeCanonicalBytes(fromB64(byId('V13').rawB64), HELD_FILE_CAP);
  ok(r.ok && r.text.charCodeAt(0) === 0xfeff && r.facts.bom === true, `V13 ${JSON.stringify(r)}`);
});
test('byte-length identity: byteLength == utf8len(C) + crlfCount + (bom ? 3 : 0) on every accepted vector', () => {
  for (const v of V) {
    const r = decodeCanonicalBytes(fromB64(v.rawB64), HELD_FILE_CAP);
    if (!r.ok) continue;
    eq(r.facts.byteLength, Buffer.byteLength(r.text, 'utf8') + r.facts.crlfCount + (r.facts.bom ? 3 : 0), `${v.id} `);
  }
});

// ── operator decode: REFUSE ────────────────────────────────────────────────────────────────────────────────────────
for (const v of V) {
  if (v.operator.result !== 'refuse') continue;
  const op = v.operator;
  test(`${v.id} refuses ${op.refusal}${op.refusal === 'invalid-utf8' ? ' (by name; TextDecoder gives no offset)' : ` @${op.offset}`}`, () => {
    const r = decodeCanonicalBytes(fromB64(v.rawB64), HELD_FILE_CAP);
    ok(!r.ok, `expected refusal, got ${JSON.stringify(r)}`);
    if (r.ok) return;
    eq(r.refusal, op.refusal, 'refusal ');
    if (op.refusal !== 'invalid-utf8') eq(r.offset, op.offset, 'offset ');
  });
}
test('V18: NUL wins over invalid UTF-8 (precedence = step order)', () => {
  const r = decodeCanonicalBytes(fromB64(byId('V18').rawB64), HELD_FILE_CAP);
  ok(!r.ok && r.refusal === 'nul-byte', JSON.stringify(r));
});
test('oversize is refused before any decode', () => {
  const r = decodeCanonicalBytes(new Uint8Array(11), 10);
  ok(!r.ok && r.refusal === 'oversize', JSON.stringify(r));
});

// ── legacy path ↔ operator decode (BC-A3) ──────────────────────────────────────────────────────────────────────────
for (const v of V) {
  test(`${v.id} legacy class ${v.legacyClass} holds`, () => {
    if (v.legacyClass === 'legacy-service-error') {
      eq(v.legacyPythonText, null, 'service error carries no text ');
      return;
    }
    const legacy = fromB64(v.legacyPythonText!.textB64).toString('utf8');
    const check = checkLegacyText(legacy);
    if (v.legacyClass === 'legacy-refused') { eq(check, v.legacyRefusal, 'legacy refusal '); return; }
    eq(check, null, 'legacy check ');
    if (v.legacyClass === 'legacy-accepts-operator-refuses') {
      ok(v.operator.result === 'refuse', 'operator must refuse');
      return;
    }
    // legacy-equal: the same baseHash as the operator path (redaction on, no secret in these vectors)
    const op = decodeCanonicalBytes(fromB64(v.rawB64), HELD_FILE_CAP);
    ok(op.ok, 'operator accepts');
    if (!op.ok) return;
    const a = canonicalBase(legacy, { redact: true });
    const b = canonicalBase(op.text, { redact: true });
    ok(a.ok && b.ok && a.baseHash === b.baseHash, `${JSON.stringify(a)} vs ${JSON.stringify(b)}`);
  });
}
test('checkLegacyText precedence: NUL > lone surrogate > CR > BOM', () => {
  eq(checkLegacyText('﻿a\r\u0000'), 'nul-byte');
  eq(checkLegacyText('﻿a\r\ud800'), 'lone-surrogate');
  eq(checkLegacyText('﻿a\r\n'), 'decode-violated');
  eq(checkLegacyText('﻿a\n'), 'legacy-bom');
  eq(checkLegacyText('a…\n'), null);
});
test('a lone surrogate is refused BEFORE any Buffer.from or hash', () => {
  const origFrom = Buffer.from;
  let calls = 0;
  (Buffer as unknown as { from: unknown }).from = (...args: unknown[]) => { calls++; return (origFrom as (...a: unknown[]) => Buffer)(...args); };
  try {
    eq(checkLegacyText('abc\udc00def'), 'lone-surrogate');
  } finally {
    (Buffer as unknown as { from: unknown }).from = origFrom;
  }
  eq(calls, 0, 'Buffer.from calls ');
});

// ── canonicalBase: R10 coupling, residual, hash ────────────────────────────────────────────────────────────────────
const BS = '\\n'; // a LITERAL backslash-n, as it appears inside a quoted string in a config file
test('redact: false ⇒ redactorVersion "none" and B === C', () => {
  const C = 'a\nb\n';
  const r = canonicalBase(C, { redact: false });
  ok(r.ok && r.B === C && r.redactorVersion === 'none' && r.redactedCount === 0 && r.baseHash === sha(C), JSON.stringify(r));
});
test('redact: true ⇒ redactorVersion === R10_VERSION', () => {
  const r = canonicalBase('a\n', { redact: true });
  ok(r.ok && r.redactorVersion === R10_VERSION, JSON.stringify(r));
});
test('V19 (built at runtime): a planted bearer_token line ⇒ redactedCount ≥ 1, baseHash ≠ sha256(C), line count unchanged', () => {
  const C = 'auth:\n  bearer_token: ' + 'abcd' + 'efgh1234567890XYZ' + '\nnext: 1\n';
  const r = canonicalBase(C, { redact: true });
  ok(r.ok, JSON.stringify(r));
  if (!r.ok) return;
  ok(r.redactedCount >= 1, 'redactedCount');
  ok(r.baseHash !== sha(C), 'baseHash must not be sha256(C)');
  eq(r.lineCount, countLines(C), 'lineCount ');
  ok(!r.B.includes('abcdefgh1234567890XYZ'), 'token must not survive in B');
});
test('JSON-config vector ({-first, literal \\n in a string, no secret): plain arm keeps the line count and every literal \\n', () => {
  const C = '{\n  "log": "a' + BS + 'b",\n  "n": 1\n}\n';
  const r = canonicalBase(C, { redact: true });
  ok(r.ok, JSON.stringify(r));
  if (!r.ok) return;
  eq(r.B, C, 'B ');
  eq(r.lineCount, 4, 'lineCount ');
});
test('V20 (SF-1, runtime): YAML string with a literal \\n before a password line ⇒ escaped-secret-residual', () => {
  const C = 'body: "header line' + BS + 'password: ' + 'hunter2' + 'secret' + BS + 'more"\nnext: 1\n';
  const r = canonicalBase(C, { redact: true });
  ok(!r.ok && r.refusal === 'escaped-secret-residual', JSON.stringify(r));
});
test('V21 (NF-1, runtime): {-first JSON whose string holds an escaped newline + escaped tab + password ⇒ escaped-secret-residual', () => {
  const C = '{\n  "banner": "line one' + BS + '\\tpassword ' + 'hunter2' + 'zz' + BS + '",\n  "x": 1\n}\n';
  const r = canonicalBase(C, { redact: true });
  ok(!r.ok && r.refusal === 'escaped-secret-residual', JSON.stringify(r));
});
test('V22 (code review sec-ops SF-1, runtime): a {-first file with a quoted "password" key (plain catches it, arm 1 is key-name blind) AND an escaped-tab secret ⇒ escaped-secret-residual — the counts must not cancel', () => {
  const C = '{\n  "password": "' + 'hunter2' + 'plainzz",\n  "banner": "line one' + BS + '\\tpassword ' + 'second2' + 'zz' + BS + '"\n}\n';
  const r = canonicalBase(C, { redact: true });
  ok(!r.ok && r.refusal === 'escaped-secret-residual', JSON.stringify(r));
});
test('control: a clean nginx log_format with a literal \\n is HELD (no false residual)', () => {
  const C = 'log_format main \'$remote_addr - $request\' "' + BS + '";\nserver { listen 80; }\n';
  const r = canonicalBase(C, { redact: true });
  ok(r.ok && r.redactedCount === 0, JSON.stringify(r));
});
test('placeholders: both spellings counted once each, never double (BC-N3); counted on C before R10', () => {
  eq(countPlaceholders('x <<REDACTED-SECRET>> y <REDACTED-SECRET> z'), 2);
  const r = canonicalBase('key: <<REDACTED-SECRET>>\n', { redact: true });
  ok(r.ok && r.preexistingPlaceholders === 1, JSON.stringify(r));
});
test('countLines: "" = 0, a final "\\n" opens no line, only "\\n" splits', () => {
  eq(countLines(''), 0);
  eq(countLines('a'), 1);
  eq(countLines('a\n'), 1);
  eq(countLines('a\n\n'), 2);
  eq(countLines('a b\fc'), 1);
});

// ── static pins (SO B1/B3, arch N1, NF-1, D6) ─────────────────────────────────────────────────────────────────────
const MOD = fs.readFileSync(path.join(__dirname, '..', 'lib', 'agents', 'harness', 'held-bytes', 'canonical-text.ts'), 'utf8');
const CODE = MOD.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '');
const R10 = fs.readFileSync(path.join(__dirname, '..', 'lib', 'agents', 'harness', 'redact-artifact-secrets.ts'), 'utf8');
test('static: the canonical module reads no environment variable', () => { ok(!CODE.includes('process.env'), 'process.env found'); });
test('static: the canonical module imports nothing from sanitize-chained-output (R9)', () => {
  ok(!MOD.includes('sanitize-chained-output'), 'R9 import found');
});
test('static: exactly one createHash( in the module, and its input is B', () => {
  eq((CODE.match(/createHash\(/g) || []).length, 1, 'createHash count ');
  ok(/createHash\('sha256'\)\.update\(Buffer\.from\(B, 'utf8'\)\)/.test(CODE), 'hash input must be B');
});
test('static: redactSecretsDeep is called once, only inside the residual comparison; B comes only from the plain arm or C', () => {
  eq((CODE.match(/redactSecretsDeep\(/g) || []).length, 1, 'redactSecretsDeep calls ');
  const deepAt = CODE.indexOf('redactSecretsDeep(');
  const residualAt = CODE.indexOf("'escaped-secret-residual' }");
  ok(deepAt > 0 && residualAt > deepAt, 'the deep walk must sit in the residual comparison');
  const assigns = CODE.match(/\bB = [^;]+;/g) || [];
  eq(assigns.sort(), ['B = C;', 'B = r.redacted;'].sort(), 'B assignments ');
  ok(/const r = redactArtifactSecrets\(C\)/.test(CODE), 'r must be the plain arm over C');
});
test('static: isR10Disabled is the ONE R10-off flag expression in the R10 module (D6)', () => {
  const r10Code = R10.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '');
  eq((r10Code.match(/=== 'false'/g) || []).length, 1, "=== 'false' count ");
  ok(/export function isR10Disabled\(\): boolean \{\s*return process\.env\.ARTIFACT_SECRET_REDACT_ENABLED === 'false';/.test(r10Code),
    'isR10Disabled body');
  eq((r10Code.match(/isR10Disabled\(\)/g) || []).length, 3, 'definition + two call sites ');
});

console.log(`\n📊 Total Tests:  ${passed + failed}`);
console.log(`✅ Passed: ${passed}`);
console.log(`❌ Total Failed: ${failed}`);
if (failed > 0) process.exit(1);
console.log('✅ All tests passed!');
